import type { CartLine } from './cart'

export interface CreateOrderInput {
  lines: CartLine[]
  code?: string
}

export interface OrderSummary {
  id: string
  subtotal: string
  discount: string
  total: string
}

import type { CartLine } from '#shared/types/cart'
import type { OrderSummary } from '#shared/types/order'

interface StoredOrder extends OrderSummary {
  lines: CartLine[]
  code?: string
}

const orders = new Map<string, StoredOrder>()
let nextOrderId = 1

export function createOrder(lines: CartLine[], code?: string): OrderSummary {
  const id = String(nextOrderId++)
  const quote = computeQuote(lines, code)
  const order: StoredOrder = {
    id,
    lines: lines.map(line => ({ ...line })),
    code,
    ...quote,
  }
  orders.set(id, order)
  return { id, subtotal: quote.subtotal, discount: quote.discount, total: quote.total }
}

export function findOrder(id: string): OrderSummary | undefined {
  const order = orders.get(id)
  if (!order)
    return
  return {
    id: order.id,
    subtotal: order.subtotal,
    discount: order.discount,
    total: order.total,
  }
}

import type { CreateOrderInput } from '#shared/types/order'

export default defineEventHandler(async (event) => {
  const body = await readBody<CreateOrderInput | undefined>(event)
  return createOrder(body?.lines ?? [], body?.code)
})

export default defineEventHandler((event) => {
  const id = getRouterParam(event, 'id') ?? ''
  const order = findOrder(id)
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})
